"""Write ``_quartodoc.yml``: one quartodoc page per module in ``src/appstat``, from the source."""

from pathlib import Path

import griffe

ROOT = Path(__file__).resolve().parent.parent
package = griffe.load("appstat", search_paths=[str(ROOT / "src")])

lines = [
    "# Generated by scripts/api_config.py (pixi run -e docs api). Do not edit.",
    "quartodoc:",
    "  package: appstat",
    "  source_dir: src",
    "  dir: reference",
    "  parser: numpy",
    "  renderer:",
    "    style: markdown",
    "    display_name: name",
    "    table_style: description-list",
    "    header_level: 2",
    "  sections:",
    "    - title: Modules",
    "      contents:",
]
for module in sorted(package.modules.values(), key=lambda m: m.name):
    if module.name.startswith("_"):
        continue
    # Defined here (not imported), public, and documented: functions, classes and constants.
    members = [
        m
        for m in module.members.values()
        if not m.is_alias
        and not m.name.startswith("_")
        and (m.is_function or m.is_class or (m.is_attribute and m.docstring))
    ]
    summary = module.docstring.parsed[0].value.splitlines()[0] if module.docstring else ""
    lines += [
        "        - kind: page",
        f"          path: {module.name}",
        "          summary:",
        f"            name: {module.name}",
        f"            desc: {summary!r}",
        "          contents:",
        *(f"            - {module.name}.{m.name}" for m in members),
    ]
(ROOT / "_quartodoc.yml").write_text("\n".join(lines) + "\n")
